// === Eingabe ===
const params = $('When Executed by Another Workflow').first().json;

// IDs aus dem kommaseparierten String parsen
const angefragteIds = (params.zutat_ids || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

if (angefragteIds.length === 0) {
  return [{ json: { 
    error: "Keine zutat_ids übergeben", 
    count: 0,
    zutaten: []
  }}];
}

// === Lookup aufbauen ===
const zutatenRows = $('Get Zutaten').all();
const zutatenMap = {};
for (const row of zutatenRows) {
  const z = row.json;
  zutatenMap[z.zutat_id] = {
    zutat_id: z.zutat_id,
    name: z.name,
    einheit: z.einheit,
    preis_pro_einheit: parseFloat(z.preis_pro_einheit) || 0,
    kategorie: z.kategorie,
    allergene: (z.allergene || '')
      .split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
  };
}

// === Angefragte IDs auflösen ===
const gefunden = [];
const nichtGefunden = [];

for (const id of angefragteIds) {
  if (zutatenMap[id]) {
    gefunden.push(zutatenMap[id]);
  } else {
    nichtGefunden.push(id);
  }
}

// === Output ===
return [{ 
  json: {
    count: gefunden.length,
    zutaten: gefunden,
    nicht_gefunden: nichtGefunden,  // damit der Agent merkt, wenn er was Falsches geraten hat
  }
}];

// === Eingaben holen ===
// Parameter vom Agent-Aufruf (durch den Trigger durchgereicht)
const params = $('When Executed by Another Workflow').first().json;

// Beide Sheets
const gerichteRows = $('Get Gerichte').all();
const zutatenRows = $('Get Zutaten').all();

// === Zutaten-Lookup aufbauen: zutat_id -> [allergene] ===
const zutatAllergene = {};
for (const row of zutatenRows) {
  const z = row.json;
  const allergene = (z.allergene || '')
    .split(',')
    .map(s => s.trim().toLowerCase())
    .filter(Boolean);
  zutatAllergene[z.zutat_id] = allergene;
}

// === Parameter parsen ===
const kategorie = (params.kategorie || '').trim().toLowerCase() || null;
const tagsMustHave = (params.tags_must_have || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const eignung = (params.eignung || '').trim().toLowerCase() || null;
const ausschlussAllergene = (params.ausschluss_allergene || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

// === Filtern ===
const results = [];
for (const row of gerichteRows) {
  const g = row.json;

  // Kategorie-Filter
  if (kategorie && (g.kategorie || '').toLowerCase() !== kategorie) continue;

  // Tags-Filter (alle müssen vorhanden sein)
  if (tagsMustHave.length > 0) {
    const gerichtTags = (g.tags || '').split(',').map(s => s.trim().toLowerCase());
    const allFound = tagsMustHave.every(t => gerichtTags.includes(t));
    if (!allFound) continue;
  }

  // Eignung-Filter
  if (eignung) {
    const gerichtEignung = (g.eignung || '').split(',').map(s => s.trim().toLowerCase());
    if (!gerichtEignung.includes(eignung)) continue;
  }

  // Allergene-Filter
  if (ausschlussAllergene.length > 0) {
    let zutatenInGericht;
    try {
      zutatenInGericht = JSON.parse(g.zutaten_json);
    } catch (e) {
      // Defekte Daten -> Gericht überspringen, statt Workflow zu crashen
      continue;
    }
    const allergeneInGericht = new Set();
    for (const z of zutatenInGericht) {
      const aList = zutatAllergene[z.zutat_id] || [];
      aList.forEach(a => allergeneInGericht.add(a));
    }
    const hasExcluded = ausschlussAllergene.some(a => allergeneInGericht.has(a));
    if (hasExcluded) continue;
  }

  // Kompakter Output — bewusst KEINE Zutaten/Beschreibung,
  // damit der Agent-Context klein bleibt
  results.push({
    gericht_id: g.gericht_id,
    name: g.name,
    kategorie: g.kategorie,
    tags: g.tags,
    eignung: g.eignung,
    zubereitungszeit_min: g.zubereitungszeit_min,
  });
}

// === Output ===
return [{ 
  json: { 
    count: results.length, 
    gerichte: results 
  } 
}];

// === Eingabe ===
const params = $('When Executed by Another Workflow').first().json;
const gesuchteId = (params.gericht_id || '').trim();

if (!gesuchteId) {
  return [{ json: { 
    error: "Kein gericht_id übergeben", 
    found: false 
  }}];
}

// === Sheets laden ===
const gerichteRows = $('Get Gerichte').all();
const zutatenRows = $('Get Zutaten').all();

// === Zutaten-Lookup aufbauen ===
const zutatenMap = {};
for (const row of zutatenRows) {
  const z = row.json;
  zutatenMap[z.zutat_id] = {
    name: z.name,
    einheit: z.einheit,
    preis_pro_einheit: parseFloat(z.preis_pro_einheit) || 0,
    allergene: (z.allergene || '')
      .split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
    kategorie: z.kategorie,
  };
}

// === Gericht suchen ===
const gericht = gerichteRows.find(row => row.json.gericht_id === gesuchteId);
if (!gericht) {
  return [{ json: { 
    error: `Gericht ${gesuchteId} nicht gefunden`, 
    found: false 
  }}];
}

const g = gericht.json;

// === Zutaten anreichern ===
let zutatenListe;
try {
  zutatenListe = JSON.parse(g.zutaten_json);
} catch (e) {
  return [{ json: { 
    error: `zutaten_json defekt für ${gesuchteId}`, 
    found: false 
  }}];
}

const zutatenDetails = [];
const allergeneGesamt = new Set();

for (const z of zutatenListe) {
  const info = zutatenMap[z.zutat_id];
  if (!info) {
    // unbekannte Zutat — anstatt zu crashen, einfach markieren
    zutatenDetails.push({
      zutat_id: z.zutat_id,
      name: '(unbekannt)',
      menge_pro_portion: z.menge_pro_portion,
      einheit: null,
      preis_pro_einheit: null,
      allergene: [],
    });
    continue;
  }
  zutatenDetails.push({
    zutat_id: z.zutat_id,
    name: info.name,
    menge_pro_portion: z.menge_pro_portion,
    einheit: info.einheit,
    preis_pro_einheit: info.preis_pro_einheit,
    kategorie: info.kategorie,
    allergene: info.allergene,
  });
  info.allergene.forEach(a => allergeneGesamt.add(a));
}

// === Output ===
return [{ 
  json: {
    found: true,
    gericht_id: g.gericht_id,
    name: g.name,
    kategorie: g.kategorie,
    tags: g.tags,
    eignung: g.eignung,
    zubereitungszeit_min: g.zubereitungszeit_min,
    beschreibung: g.beschreibung,
    allergene_im_gericht: Array.from(allergeneGesamt).sort(),
    zutaten: zutatenDetails,
  }
}];

